/* ==UserStyle==
@name         Todoist Catppuccin
@namespace    github.com/titandrive/userstyles/styles/todoist
@homepageURL  https://github.com/titandrive/stylus_themes/tree/main/todoist
@version      1.0.0
@updateURL    https://raw.githubusercontent.com/titandrive/stylus_themes/main/todoist/catppuccin.user.css
@description  Soothing pastel theme for Todoist
@author       titandrive
@license      MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/lib.less";

@-moz-document domain("todoist.com") {

  html.theme_light {
    #catppuccin(@lightFlavor);
  }

  html.theme_dark {
    #catppuccin(@darkFlavor);
  }

  html:not(.theme_light):not(.theme_dark) {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --background-primary: @base !important;
    --background-secondary: @mantle !important;
    --background-tertiary: @crust !important;
    --background-elevated: @surface0 !important;
    --background-hover: @surface0 !important;
    --background-selected: @surface1 !important;
    --background-tinted: @surface0 !important;

    --color-base-primary: @base !important;
    --color-base-secondary: @mantle !important;
    --color-base-tertiary: @crust !important;
    --color-surface-0: @surface0 !important;
    --color-surface-1: @surface1 !important;
    --color-surface-2: @surface2 !important;

    --left-menu-background: @mantle !important;

    --reactist-bg-default: @base !important;
    --reactist-bg-aside: @mantle !important;
    --reactist-bg-menu: @surface0 !important;
    --reactist-bg-toast: @surface0 !important;
    --reactist-bg-selected: @surface1 !important;
    --reactist-bg-highlight: fade(@accent, 15%) !important;
    --reactist-framework-fill-background: @mantle !important;
    --reactist-field-readonly-background: @mantle !important;
    --reactist-banner-background-color: @mantle !important;
    --reactist-alert-tone-caution-background: @mantle !important;
    --reactist-alert-tone-critical-background: @mantle !important;
    --reactist-alert-tone-info-background: @mantle !important;
    --reactist-alert-tone-positive-background: @mantle !important;

    --product-library-background-base-primary: @base !important;
    --product-library-background-base-secondary: @mantle !important;
    --product-library-background-base-tertiary: @crust !important;
    --product-library-background-grouped-primary: @mantle !important;
    --product-library-background-grouped-secondary: @base !important;
    --product-library-background-grouped-tertiary: @crust !important;
    --product-library-background-raised-primary: @surface0 !important;
    --product-library-background-raised-secondary: @surface1 !important;
    --product-library-background-raised-tertiary: @surface0 !important;
    --product-library-background-raised-quaternary: @surface2 !important;
    --product-library-selectable-background: @surface0 !important;

    --settings-card-idle-fill: @mantle !important;
    --settings-card-hover-fill: @surface0 !important;
    --scrollbar-dark-fill: @mantle !important;
    --scrollbar-thumb-track: @base !important;
    --doist-card-background: @surface0 !important;
    --brand-secondary-background: @mantle !important;

    /* ── Text ─────────────────────────────────────────────── */
    --text-primary: @text !important;
    --text-secondary: @subtext0 !important;
    --text-muted: @overlay0 !important;
    --text-faded: @overlay0 !important;
    --text-danger: @red !important;
    --text-warning: @yellow !important;
    --text-success: @green !important;

    --color-text-primary: @text !important;
    --color-text-secondary: @subtext0 !important;
    --color-text-muted: @overlay0 !important;

    --reactist-content-primary: @text !important;
    --reactist-content-secondary: @subtext0 !important;
    --reactist-content-tertiary: @overlay0 !important;
    --reactist-content-danger: @red !important;
    --reactist-content-positive: @green !important;
    --reactist-banner-main-copy-color: @text !important;
    --reactist-banner-secondary-copy-color: @subtext0 !important;
    --reactist-field-placeholder-tint: @overlay0 !important;

    --product-library-display-primary-idle-tint: @text !important;
    --product-library-display-secondary-idle-tint: @subtext0 !important;
    --product-library-display-tertiary-idle-tint: @overlay0 !important;

    /* ── Accent ───────────────────────────────────────────── */
    --color-accent: @accent !important;
    --color-accent-hover: lighten(@accent, 5%) !important;
    --interactive-accent: @accent !important;
    --interactive-accent-hover: lighten(@accent, 5%) !important;
    --color-interactive-accent: @accent !important;

    --reactist-actionable-primary-idle-fill: @accent !important;
    --reactist-actionable-primary-hover-fill: lighten(@accent, 5%) !important;
    --reactist-actionable-primary-idle-tint: @base !important;
    --reactist-actionable-primary-hover-tint: @base !important;
    --reactist-actionable-primary-disabled-fill: @surface1 !important;
    --reactist-actionable-primary-disabled-tint: @overlay0 !important;
    --reactist-bg-brand: @accent !important;
    --reactist-progressbar-fill: @accent !important;
    --reactist-switch-checked: @accent !important;
    --reactist-spinner-tint: @accent !important;
    --reactist-spinner-fill: @surface1 !important;

    --product-library-actionable-primary-idle-fill: @accent !important;
    --product-library-actionable-primary-hover-fill: lighten(@accent, 5%) !important;
    --product-library-actionable-primary-on-idle-tint: @base !important;
    --product-library-actionable-primary-on-hover-tint: @base !important;
    --product-library-actionable-primary-disabled-fill: @surface1 !important;
    --product-library-actionable-primary-on-dark-idle-fill: @accent !important;
    --product-library-actionable-primary-on-dark-hover-fill: lighten(@accent, 5%) !important;
    --product-library-actionable-primary-on-dark-on-idle-tint: @base !important;
    --product-library-actionable-primary-on-dark-on-hover-tint: @base !important;
    --product-library-selectable-primary-selected-fill: @accent !important;
    --product-library-selectable-primary-selected-tint: lighten(@accent, 5%) !important;

    /* ── Borders ──────────────────────────────────────────── */
    --color-border: @surface0 !important;
    --color-border-subtle: @surface1 !important;
    --border-subtle: @surface0 !important;
    --border-default: @surface1 !important;

    --reactist-inputs-idle: @surface1 !important;
    --reactist-inputs-hover: @surface2 !important;
    --reactist-inputs-focus: @accent !important;
    --reactist-inputs-alert: @red !important;
    --reactist-divider-color: @surface0 !important;
    --reactist-divider-primary: @surface0 !important;
    --reactist-divider-secondary: @mantle !important;
    --reactist-divider-tertiary: @surface1 !important;
    --reactist-banner-border-color: @surface0 !important;
    --reactist-alert-tone-caution-border: @surface0 !important;
    --reactist-alert-tone-critical-border: @surface0 !important;
    --reactist-alert-tone-info-border: @surface0 !important;
    --reactist-alert-tone-positive-border: @surface0 !important;
    --reactist-tab-neutral-border: @surface0 !important;
    --reactist-tab-neutral-track: @mantle !important;
    --reactist-tab-neutral-selected-fill: @surface0 !important;
    --reactist-tab-neutral-selected-tint: @text !important;
    --reactist-tab-neutral-unselected-tint: @subtext0 !important;
    --reactist-prose-code-border: @surface0 !important;
    --reactist-prose-code-fill: @mantle !important;
    --reactist-prose-horizontal-rule-color: @surface0 !important;

    --product-library-border-idle-tint: @surface0 !important;
    --product-library-border-hover-tint: @surface1 !important;
    --product-library-border-focus-tint: @accent !important;
    --product-library-divider-primary: @surface0 !important;
    --product-library-divider-secondary: @mantle !important;
    --product-library-divider-tertiary: @surface1 !important;
    --product-library-divider-on-dark: @surface1 !important;
    --settings-card-idle-border-color: @surface0 !important;
    --settings-card-hover-border-color: @surface1 !important;

    /* ── Scrollbars ───────────────────────────────────────── */
    --scrollbar-thumb-idle: @surface1 !important;
    --scrollbar-thumb-hover: @surface2 !important;
    --reactist-scrollbar-thumb-idle: fade(@surface2, 80%) !important;

    /* ── Focus ring ───────────────────────────────────────── */
    --focus-marker-box-shadow: 0 0 0 1px @accent, 0 0 0 4px fade(@accent, 30%) !important;
    --focus-marker-box-shadow-inner: @accent !important;
    --focus-marker-box-shadow-outer: fade(@accent, 30%) !important;

    /* ── Links ────────────────────────────────────────────── */
    --reactist-text-link-idle-tint: @blue !important;
    --reactist-text-link-hover-tint: @lavender !important;
    --reactist-prose-link-hover-tint: @lavender !important;

    /* ── Icon/quaternary buttons ──────────────────────────── */
    --reactist-actionable-quaternary-idle-tint: @subtext0 !important;
    --reactist-actionable-quaternary-hover-tint: @text !important;
    --reactist-actionable-quaternary-hover-fill: fade(@accent, 15%) !important;
    --product-library-actionable-quaternary-idle-tint: @subtext0 !important;
    --product-library-actionable-quaternary-hover-tint: @text !important;
    --product-library-actionable-quaternary-on-dark-idle-tint: @subtext0 !important;
    --product-library-actionable-quaternary-on-dark-hover-tint: @text !important;
    --product-library-actionable-quaternary-on-dark-hover-fill: @surface0 !important;
    --product-library-actionable-focus-fill: @surface0 !important;
    --reactist-actionable-focus-fill: @surface0 !important;

    /* ── Error/warning/success ────────────────────────────── */
    --color-error: @red !important;
    --color-warning: @yellow !important;
    --color-success: @green !important;

    /* Override Todoist's hardcoded brand red with accent */
    --reactist-actionable-tertiary-idle-tint: @accent !important;
    --reactist-actionable-tertiary-hover-tint: lighten(@accent, 5%) !important;
    --reactist-actionable-tertiary-on-dark-idle-tint: @accent !important;
    --reactist-actionable-tertiary-on-dark-hover-tint: lighten(@accent, 5%) !important;
    --product-library-actionable-tertiary-idle-tint: @accent !important;
    --product-library-actionable-tertiary-hover-tint: lighten(@accent, 5%) !important;
    --product-library-actionable-tertiary-on-dark-idle-tint: @accent !important;
    --product-library-actionable-tertiary-on-dark-hover-tint: lighten(@accent, 5%) !important;
    --product-library-display-accent-primary-fill: @accent !important;
    --product-library-display-accent-primary-tint: @accent !important;
    --reactist-bg-selected: @surface1 !important;
    --reactist-badge-attention-tint: @accent !important;
    --product-library-selectable-secondary-selected-fill: fade(@accent, 20%) !important;
    --product-library-selectable-secondary-on-selected-fill: @accent !important;
    --product-library-selectable-secondary-on-selected-tint: @accent !important;

    /* Schedule / due date colors */
    --product-library-schedule-overdue-fill: @red !important;
    --product-library-schedule-overdue-tint: @red !important;
    --product-library-schedule-today-fill: @green !important;
    --product-library-schedule-today-tint: @green !important;
    --product-library-schedule-tomorrow-fill: @peach !important;
    --product-library-schedule-tomorrow-tint: @peach !important;
    --product-library-schedule-next-week-fill: @mauve !important;
    --product-library-schedule-next-week-tint: @mauve !important;
    --product-library-schedule-weekend-fill: @blue !important;
    --product-library-schedule-weekend-tint: @blue !important;
    --product-library-schedule-postpone-fill: @blue !important;
    --product-library-schedule-postpone-tint: @blue !important;
    --product-library-schedule-no-date-fill: @overlay0 !important;
    --product-library-schedule-no-date-tint: @overlay0 !important;

    /* ── Element overrides ────────────────────────────────── */
    html, body, #todoist_app, #todoist_app > div {
      background-color: @base !important;
      color: @text !important;
    }

    .task_editor__footer {
      background-color: @mantle !important;
    }

    .task_editor__editing_area {
      border-bottom: none !important;
    }

    .task_editor,
    .quick_add__body,
    .quick_add__body > div,
    .quick_add__body > div > div,
    form[data-testid="task-editor"],
    form[data-testid="task-editor"] > div {
      background-color: @base !important;
    }

    /* Sidebar active item and add task button accent color */
    [class*="add_task_top_row"] span,
    [data-testid="add-task-top"] span {
      color: @accent !important;
    }

    ::-webkit-scrollbar { width: 6px; height: 6px; }
    ::-webkit-scrollbar-track { background: @mantle; }
    ::-webkit-scrollbar-thumb { background: @surface1; border-radius: 3px; }
    ::-webkit-scrollbar-thumb:hover { background: @surface2; }

    /* Tasks/Comments tab buttons */
    button#tasks[aria-selected="true"],
    button#comments[aria-selected="true"] {
      background-color: @surface0 !important;
      color: @text !important;
    }

    button#tasks[aria-selected="false"],
    button#comments[aria-selected="false"] {
      background-color: transparent !important;
      color: @subtext0 !important;
    }

    /* Sidebar list item + section header hover */
    div[id^="sidebar-list-item"]:hover,
    div[sidebar-list-item="true"]:hover,
    div[data-drag-over="false"]:hover,
    [data-testid="project-list-item"] > div:hover,
    [data-testid="project-list-item"]:hover > div,
    li[type="project_list_item"]:hover > div,
    li[type="project_list_item"]:hover div[id^="sidebar-list-item"],
    [data-testid="sidebar-section-header"]:hover,
    [data-testid*="section"]:hover > div,
    li[type="section_list_item"]:hover > div,
    li[type="section_list_item"]:hover div[id^="sidebar-list-item"],
    .JczMOAc:hover {
      background-color: @surface0 !important;
    }

    /* Menu item hover — overrides hardcoded reactist styles */
    [role="menu"] [role="menuitem"]:hover,
    [role="menu"] [role="menuitem"]:focus,
    [role="menubar"] [role="menuitem"]:hover,
    [role="menubar"] [role="menuitem"]:focus {
      background-color: @surface1 !important;
    }

    /* Loading screen */
    #loading,
    .loading_screen {
      background-color: @base !important;
      color: @text !important;
    }

    .loading_screen svg {
      fill: @accent !important;
    }

    .loading_screen--logo .logo_bg {
      fill: @accent !important;
    }

    .loading_screen--logo .logo_stripe {
      fill: @base !important;
    }
  }
}

/* ==UserStyle==
@name WhatsApp Web Catppuccin
@namespace github.com/catppuccin/userstyles/styles/whatsapp-web
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/whatsapp-web
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/whatsapp-web/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Awhatsapp-web
@description Soothing pastel theme for WhatsApp Web
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]

@var checkbox lighterMessages "Elevated incoming messages" 0
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("web.whatsapp.com") {
  /* Note: Some variables appear to be applied on :root,
  but without using :has there doesn't seem to be a good
  way to target the root whenever a certain theme is applied.
  */

  :root:has(> :not(.dark)),
  :root .color-refresh,
  .color-refresh,
  /* Layer under mount */
  .app-wrapper-web.app-wrapper-web,
  .app-wrapper-web.app-wrapper-web:root {
    #catppuccin(@lightFlavor);
  }

  :root:has(> .dark),
  .dark.color-refresh,
  .color-refresh.dark,
  /* Layer under mount */
  .dark .app-wrapper-web.app-wrapper-web,
  .dark .app-wrapper-web.app-wrapper-web:root {
    #catppuccin(@darkFlavor);
  }

  #initialLoad(@styles) {
    #RGB(splashscreen-startup-background, @styles[@crust]) !important;
    #RGB(splashscreen-startup-icon, @styles[@surface0]) !important;

    #RGB(splashscreen-primary-title, @styles[@text]) !important;

    #RGB(splashscreen-progress-primary, @styles[@@accentColor]) !important;
    #RGB(splashscreen-progress-background, @styles[@surface1]) !important;

    #RGB(splashscreen-secondary-lighter, @styles[@overlay2]) !important;

    #RGB(startup-icon, @styles[@surface1]) !important;
    #RGB(startup-background, @styles[@crust]) !important;

    #RGB(progress-background, @styles[@overlay0]) !important;
  }

  // Inital loading screen (Avoid FOUC)
  [style^="--splashscreen-startup-background: #F7F5F3;"] {
    #initialLoad(@catppuccin[@@lightFlavor]);
  }

  [style^="--splashscreen-startup-background: #0A1014;"] {
    #initialLoad(@catppuccin[@@darkFlavor]);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    @accentContent: if(@flavor = latte, @base, @crust);

    @emphasize: 10%;
    @deemphasize: if(@flavor = latte, 15%, 30%);
    @bubble-surface-deemp: 20%;

    @scrim: 30%;
    @pressed: 20%;

    #WDS(accent, @accent);
    #WDS(accent-deemphasized, fade(@accent, @deemphasize));
    #WDS(accent-emphasized, lighten(@accent, @emphasize));

    #WDS(secondary-negative, @red);
    #WDS(secondary-negative-deemphasized, fade(@red, @deemphasize));
    #WDS(secondary-negative-emphasized, @red);

    #WDS(secondary-positive, @green);
    #WDS(secondary-positive-deemphasized, fade(@green, @deemphasize));

    #WDS(secondary-warning, @yellow);
    #WDS(secondary-warning-deemphasized, fade(@yellow, @deemphasize));

    #WDS(content-default, @text);
    #WDS(content-deemphasized, @overlay2);
    #WDS(content-disabled, fade(@text, 50%));

    #WDS(content-on-accent, @accentContent);
    #WDS(content-action-default, @accent);
    #WDS(content-action-emphasized, lighten(@accent, @emphasize));
    #WDS(content-external-link, @blue);
    #WDS(content-inverse, @crust);
    #WDS(content-read, @blue);

    #WDS(background-wash-inset, @crust);
    #WDS(background-wash-plain, @crust);
    #WDS(background-elevated-wash-plain, @crust);
    #WDS(background-elevated-wash-inset, @crust);
    #WDS(background-dimmer, fade(#000, @scrim));
    #WDS(modal-backdrop-solid, @crust);

    #WDS(surface-default, @mantle);
    --background-default: var(--WDS-surface-default);
    --search-container-background: var(--WDS-surface-default);
    #WDS(surface-emphasized, @base);
    #WDS(surface-elevated-default, @base);
    #WDS(surface-elevated-emphasized, mix(@text, @base, @emphasize));
    #WDS(surface-highlight, fade(@text, @pressed));
    #WDS(surface-inverse, @text);
    #WDS(surface-pressed, fade(@text, @pressed));

    #WDS(lines-divider, fade(@text, 10%));
    #WDS(lines-outline-default, @overlay0);
    #WDS(lines-outline-deemphasized, fade(@text, @deemphasize));

    #WDS(persistent-activity-indicator, fade(@green, 90%));
    #WDS(persistent-always-black, #000);
    #WDS(persistent-always-white, #fff);
    #WDS(persistent-always-branded, @accent);

    #WDS(
      systems-bubble-surface-incoming,
      if(@lighterMessages = 1, @surface1, @base),
    );

    #WDS(
      systems-bubble-surface-outgoing,
      mix(@accent, @base, @bubble-surface-deemp),
    );
    #WDS(systems-bubble-content-deemphasized, fade(@text, 50%));

    #WDS(systems-bubble-surface-overlay, @mantle);
    #WDS(systems-bubble-surface-system, @mantle);

    #WDS(
      systems-bubble-surface-e2e,
      mix(@yellow, @mantle, @bubble-surface-deemp),
    );
    #WDS(systems-bubble-content-e2e, @yellow);

    #WDS(
      systems-bubble-surface-business,
      mix(@teal, @mantle, @bubble-surface-deemp),
    );

    #WDS(systems-chat-surface-composer, @base);
    #WDS(systems-chat-background-wallpaper, @crust);
    #WDS(systems-chat-foreground-wallpaper, @mantle);
    #WDS(systems-chat-surface-tray, @base);
    #WDS(systems-status-seen, fade(@text, 50%));

    #WDS(components-platform-gesture-bar, fade(@crust, 50%));
    #WDS(components-platform-status-bar, fade(@crust, 80%));
    #WDS(components-surface-nav-bar, @base);

    #WDS(app-wash, @surface0);

    #WDS(white, @crust);
    #RGB(white, @crust);

    #RGB(attachment-type-stickers-color, @green);
    #RGB(attachment-type-polls-color, @yellow);
    #RGB(attachment-type-contacts-color, @sky);
    #RGB(attachment-type-camera-color, @pink);
    #RGB(attachment-type-photos-color, @blue);
    #RGB(attachment-type-documents-color, @mauve);
    #RGB(attachment-type-audio-color, @peach);
    /* \/ Note: Seems to be overwritten by a generated
    CSS variable, so has no effect :( */
    #RGB(attachment-type-event-color, @pink);

    #RGB(toast-background, @surface1);
    #RGB(toast-text, @text);

    #RGB(picker-background, @surface1);

    #RGB(butterbar-blue-nux-background, @sky);
    #RGB(butterbar-blue-nux-icon-background, darken(@sky, 30%));
    #RGB(blue-light, @blue);

    #RGB(gray-500, @overlay2);

    #RGB(focus-animation, mix(@accent, @base, 40%));
    #RGB(focus-animation-deeper, mix(@accent, @base, 30%));

    #RGB(startup-icon, @surface1);
    #RGB(startup-background, @crust);

    #RGB(progress-background, @surface0);

    /* "About AI messages" icon */
    .st0 {
      fill: @accent !important;
